def chain_of_tokens(chain):
    tokens = list(chain)
    n = len(tokens)
    if n == 0:
        return []

    # Find the first token that is not the first token
    for i in range(1, n):
        if tokens[i] != tokens[0]:
            break

    # Find the first token that is the first token
    first_token = tokens[0]
    for i in range(1, n):
        if tokens[i] == first_token:
            break

    # Find the last token that is the last token
    for i in range(n-1, -1, -1):
        if tokens[i] != tokens[-1]:
            break

    # Find the last token that is the last token
    last_token = tokens[-1]
    for i in range(n-1, -1, -1):
        if tokens[i] == last_token:
            break

    # Generate the chain
    chain_parts = []
    current_token = first_token
    for i in range(1, n):
        chain_parts.append(current_token)
        current_token = tokens[i]
    chain_parts.append(last_token)

    return chain_parts

